#!/usr/bin/env node
/**
 * scripts/build-admin-bundle.js
 * 把 pages/admin/*.js 按 admin.html 里的加载顺序合并到 assets/admin-bundle.js
 * pages/admin.js 单独保留（主入口，不在 bundle 里）
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const ADMIN_HTML = path.join(ROOT, 'admin.html');
const OUT_FILE = path.join(ROOT, 'assets/admin-bundle.js');

// 1. 从 admin.html 解析出当前加载顺序
const html = fs.readFileSync(ADMIN_HTML, 'utf8');
const re = /<script\s+src="(pages\/admin\/[\w\-]+\.js)(?:\?[^"]*)?"[^>]*>\s*<\/script>/g;
const files = [];
let m;
while ((m = re.exec(html)) !== null) {
    files.push(m[1]);
}

if (files.length === 0) {
    console.error('❌ 未在 admin.html 找到任何 pages/admin/*.js');
    process.exit(1);
}

console.log(`📦 从 admin.html 解析出 ${files.length} 个 admin 子模块`);

// 2. 拼接（保持原顺序）
let bundle = `/* ============================================================
   AUTO-GENERATED by scripts/build-admin-bundle.js — DO NOT EDIT
   源码位置: pages/admin/*.js
   重新生成: npm run build:admin
   生成时间: ${new Date().toISOString()}
   包含 ${files.length} 个模块：
${files.map(f => '     - ' + path.basename(f)).join('\n')}
   ============================================================ */
`;

let totalBytes = 0;
for (const f of files) {
    const fullPath = path.join(ROOT, f);
    if (!fs.existsSync(fullPath)) {
        console.error(`❌ 文件不存在: ${f}`);
        process.exit(1);
    }
    const content = fs.readFileSync(fullPath, 'utf8');
    totalBytes += Buffer.byteLength(content, 'utf8');
    bundle += `\n/* ========== ${f} ========== */\n`;
    bundle += content;
    bundle += '\n';
}

// 3. 写文件
fs.mkdirSync(path.dirname(OUT_FILE), { recursive: true });
fs.writeFileSync(OUT_FILE, bundle, 'utf8');

const outSize = Buffer.byteLength(bundle, 'utf8');
console.log(`✅ assets/admin-bundle.js 生成完成`);
console.log(`   源码合计: ${(totalBytes/1024).toFixed(1)} KB`);
console.log(`   打包产物: ${(outSize/1024).toFixed(1)} KB`);

// 4. 更新 admin.html
const ts = Date.now();
let newHtml = html;

// 4a. 找到第一个 admin/*.js 的位置，记录其缩进
const firstMatch = html.match(/([\t ]*)<script\s+src="pages\/admin\/[\w\-]+\.js[^"]*"[^>]*>\s*<\/script>/);
if (!firstMatch) {
    console.error('❌ 未找到可替换的 admin 子模块 script 标签');
    process.exit(1);
}
const indent = firstMatch[1] || '';

// 4b. 删除所有 pages/admin/*.js 的 script 标签
newHtml = newHtml.replace(
    /[\t ]*<script\s+src="pages\/admin\/[\w\-]+\.js(?:\?[^"]*)?"[^>]*>\s*<\/script>\s*\n?/g,
    ''
);

// 4c. 在原位置插入 bundle 引用
const bundleTag = `${indent}<script src="assets/admin-bundle.js?v=${ts}"></script>\n`;
// 找 pages/admin.js 的引用位置（它还在）
const mainJsRe = /([\t ]*)<script\s+src="pages\/admin\.js(?:\?[^"]*)?"[^>]*>\s*<\/script>/;
const mainMatch = newHtml.match(mainJsRe);
if (!mainMatch) {
    console.error('❌ 未找到 pages/admin.js（主入口）');
    process.exit(1);
}
newHtml = newHtml.replace(mainJsRe, `${bundleTag}${mainMatch[0]}`);

// 4d. 更新 pages/admin.js 的版本号
newHtml = newHtml.replace(
    /(pages\/admin\.js\?v=)\d+/g,
    `$1${ts}`
);

fs.writeFileSync(ADMIN_HTML, newHtml, 'utf8');
console.log(`✅ admin.html 已更新`);
console.log(`   - 删除 ${files.length} 个 script 标签`);
console.log(`   - 插入 1 个 assets/admin-bundle.js?v=${ts}`);
console.log(`   - pages/admin.js 版本号也刷新到 ${ts}`);
